"""Offline golden generator: exact rationals and integer RN/ties-to-even.

No host floating-point arithmetic, production helper, or third-party dependency.
Run from any directory; writes raster_boundaries.inc next to this file.
"""
from fractions import Fraction
from pathlib import Path


def power2(exponent):
    return Fraction(2 ** exponent) if exponent >= 0 else Fraction(1, 2 ** -exponent)


def rational(bits):
    exponent = (bits >> 52) & 2047
    mantissa = bits & ((1 << 52) - 1)
    assert exponent != 2047
    value = mantissa * power2(-1074) if exponent == 0 else (
        ((1 << 52) + mantissa) * power2(exponent - 1023 - 52))
    return -value if bits >> 63 else value


def rn(value):
    sign = (1 << 63) if value < 0 else 0
    value = abs(value)
    if not value:
        return sign
    exponent = value.numerator.bit_length() - value.denominator.bit_length()
    if value < power2(exponent):
        exponent -= 1
    scaled = value / power2(max(exponent - 52, -1074))
    quotient, remainder = divmod(scaled.numerator, scaled.denominator)
    if 2 * remainder > scaled.denominator or (
            2 * remainder == scaled.denominator and quotient % 2):
        quotient += 1
    if quotient < 1 << 52:
        return sign | quotient
    if quotient == 1 << 53:
        quotient >>= 1
        exponent += 1
    exponent = max(exponent, -1022)
    if exponent > 1023:
        return sign | (2047 << 52)
    return sign | ((exponent + 1023) << 52) | (quotient - (1 << 52))


def decimal(text):
    return rn(Fraction(text))


assert rn(Fraction(1) + power2(-53)) == 0x3ff0000000000000
assert rn(Fraction(1) + 3 * power2(-53)) == 0x3ff0000000000002
assert rn(power2(-1075)) == 0
assert rn(3 * power2(-1075)) == 2

cases = [
    ("terminal-0.1", 0, decimal("0.1"), 0x3fd3333333333334),
    ("decimal-0.3", 0, decimal("0.1"), decimal("0.3")),
    ("positive-unit", decimal("1.25"), decimal("1"), decimal("4.25")),
    ("negative-unit", decimal("-3"), decimal("1"), 0),
    ("cross-zero", decimal("-0.25"), decimal("0.1"), decimal("0.2")),
    ("six-decimal-0.01", decimal("1234.567890"), decimal("0.01"), decimal("1234.597890")),
    ("six-decimal-0.001", decimal("-9999.999999"), decimal("0.001"), decimal("-9999.995999")),
    ("six-decimal-micro", decimal("9999.999999"), decimal("0.000001"), decimal("10000.000003")),
    ("binary-step", decimal("-1.5"), decimal("0.125"), decimal("-1.125")),
    ("subnormal", 0, 1, 4),
    ("large", 0x7e37e43c8800759c, rn(power2(944)), 0x7e37e43c8800759f),
    ("no-contraction", decimal("-1"), decimal("0.1"), 0x3fb99999999999a0),
    ("addition-ties-even", decimal("1"), rn(3 * power2(-53)), 0x3ff0000000000004),
    ("multiplication-ties-even", 0, 0x3ff0000000000001, 0x4008000000000002),
]

lines = ["// Generated by generate_boundaries.py; integer/rational binary64 oracle."]
for name, origin, cell, maximum in cases:
    boundaries = [origin]
    for i in range(1, 100):
        product = rn(i * rational(cell))
        current = rn(rational(origin) + rational(product))
        assert rational(current) > rational(boundaries[-1])
        boundaries.append(current)
        if rational(current) >= rational(maximum):
            break
    else:
        raise AssertionError("fixture too large")
    bits = lambda value: f"0x{value:016x}ULL"
    lines.append(f'{{"{name}", {bits(origin)}, {bits(cell)}, {bits(maximum)},')
    lines.append(" {" + ", ".join(map(bits, boundaries)) + "}},")
Path(__file__).with_name("raster_boundaries.inc").write_text("\n".join(lines) + "\n", encoding="utf-8")
